import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] u, v;
    static int[] orderU, orderV, rankU, rankV;
    static int[] nextU, prevU, nextV, prevV;
    static int[] color, queue;
    static int firstU, lastU, firstV, lastV;
    static int[] minU = new int[2], maxU = new int[2];
    static int[] minV = new int[2], maxV = new int[2];

    static void removePoint(int p) {
        int r = rankU[p];
        int a = prevU[r], b = nextU[r];
        if (a >= 0) nextU[a] = b;
        else firstU = b;
        if (b >= 0) prevU[b] = a;
        else lastU = a;

        r = rankV[p];
        a = prevV[r];
        b = nextV[r];
        if (a >= 0) nextV[a] = b;
        else firstV = b;
        if (b >= 0) prevV[b] = a;
        else lastV = a;
    }

    static void assign(int p, int c, int tail) {
        color[p] = c;
        queue[tail] = p;

        if (u[p] < minU[c]) minU[c] = u[p];
        if (u[p] > maxU[c]) maxU[c] = u[p];
        if (v[p] < minV[c]) minV[c] = v[p];
        if (v[p] > maxV[c]) maxV[c] = v[p];

        removePoint(p);
    }

    static boolean feasible(int d) {
        Arrays.fill(color, -1);

        for (int i = 0; i < n; i++) {
            nextU[i] = nextV[i] = i + 1 < n ? i + 1 : -1;
            prevU[i] = prevV[i] = i - 1;
        }
        firstU = firstV = 0;
        lastU = lastV = n - 1;

        for (int c = 0; c < 2; c++) {
            minU[c] = minV[c] = Integer.MAX_VALUE;
            maxU[c] = maxV[c] = Integer.MIN_VALUE;
        }

        int tail = 0;

        for (int seed = 0; seed < n; seed++) {
            if (color[seed] != -1) continue;

            tail = 0;
            assign(seed, 0, tail++);

            int head = 0;
            while (head < tail) {
                int p = queue[head++];
                int c = color[p];
                int opposite = c ^ 1;

                long lowerU = (long) u[p] - d;
                long upperU = (long) u[p] + d;
                long lowerV = (long) v[p] - d;
                long upperV = (long) v[p] + d;

                if (minU[c] < lowerU || maxU[c] > upperU ||
                    minV[c] < lowerV || maxV[c] > upperV) {
                    return false;
                }

                while (true) {
                    int q = -1;

                    if (firstU != -1) {
                        int candidate = orderU[firstU];
                        if (u[candidate] < lowerU) q = candidate;
                    }
                    if (q == -1 && lastU != -1) {
                        int candidate = orderU[lastU];
                        if (u[candidate] > upperU) q = candidate;
                    }
                    if (q == -1 && firstV != -1) {
                        int candidate = orderV[firstV];
                        if (v[candidate] < lowerV) q = candidate;
                    }
                    if (q == -1 && lastV != -1) {
                        int candidate = orderV[lastV];
                        if (v[candidate] > upperV) q = candidate;
                    }

                    if (q == -1) break;
                    assign(q, opposite, tail++);
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();

        int[] x = new int[n];
        int[] y = new int[n];
        for (int i = 0; i < n; i++) x[i] = fs.nextInt();
        for (int i = 0; i < n; i++) y[i] = fs.nextInt();

        u = new int[n];
        v = new int[n];
        long[] keysU = new long[n];
        long[] keysV = new long[n];

        for (int i = 0; i < n; i++) {
            u[i] = x[i] + y[i];
            v[i] = x[i] - y[i];
            keysU[i] = ((long) u[i] << 32) | (i & 0xffffffffL);
            keysV[i] = ((long) (v[i] + 500_000_000) << 32) | (i & 0xffffffffL);
        }

        Arrays.sort(keysU);
        Arrays.sort(keysV);

        orderU = new int[n];
        orderV = new int[n];
        rankU = new int[n];
        rankV = new int[n];

        for (int i = 0; i < n; i++) {
            int pU = (int) keysU[i];
            orderU[i] = pU;
            rankU[pU] = i;

            int pV = (int) keysV[i];
            orderV[i] = pV;
            rankV[pV] = i;
        }

        nextU = new int[n];
        prevU = new int[n];
        nextV = new int[n];
        prevV = new int[n];
        color = new int[n];
        queue = new int[n];

        int low = -1, high = 1_000_000_000;
        while (high - low > 1) {
            int mid = low + (high - low) / 2;
            if (feasible(mid)) high = mid;
            else low = mid;
        }

        System.out.println(high);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr, len;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
